);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(92779698949599516)
,p_plug_name=>'SQL Scripts - Output Export'
,p_static_id=>'sql-scripts-output-export'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div style="font-family: Arial, sans-serif; color: #263238; max-width: 980px; line-height: 1.6;">',
'',
'  <div style="background: #f2f7fc; border-left: 5px solid #1976d2; border-radius: 6px; padding: 18px 22px; margin-bottom: 20px;">',
'    <div style="font-size: 24px; font-weight: 700; margin-bottom: 6px;">',
unistr('      \D83D\DCE6 Update order items and download a CSV'),
'    </div>',
'    <div style="color: #455a64;">',
unistr('      Set up the OCI credential, run the SQL Script to update the selected product\2019s order items and export them,'),
'      then download the CSV from your APEX page.',
'    </div>',
'  </div>',
'',
'  <div style="display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 22px;">',
'',
'    <div style="flex: 1 1 220px; border: 1px solid #dce3e8; border-radius: 6px; padding: 14px;">',
unistr('      <div style="font-size: 18px; font-weight: 700; margin-bottom: 5px;">\D83D\DD10 1. Set up access</div>'),
unistr('      <div>Create the Object Storage credential once in the APEX page\2019s parsing schema.</div>'),
'    </div>',
'',
'    <div style="flex: 1 1 220px; border: 1px solid #dce3e8; border-radius: 6px; padding: 14px;">',
unistr('      <div style="font-size: 18px; font-weight: 700; margin-bottom: 5px;">\D83D\DD04 2. Update and export</div>'),
'      <div>The SQL Script copies product rows to the GTT, increases quantity, updates the main table, then exports matching rows as CSV.</div>',
'    </div>',
'',
'    <div style="flex: 1 1 220px; border: 1px solid #dce3e8; border-radius: 6px; padding: 14px;">',
unistr('      <div style="font-size: 18px; font-weight: 700; margin-bottom: 5px;">\2B07\FE0F 3. Download</div>'),
'      <div>An APEX page process retrieves the CSV from Object Storage and sends it to the browser.</div>',
'    </div>',
'',
'  </div>',
'',
'  <div style="border: 1px solid #dce3e8; border-radius: 6px; padding: 16px 18px; margin-bottom: 20px;">',
'    <div style="font-size: 19px; font-weight: 700; margin-bottom: 6px;">',
unistr('      \D83D\DD10 Step 1: Create the OCI credential'),
'    </div>',
'    <div style="color: #455a64; margin-bottom: 10px;">',
'      Run this once as the parsing schema used by the APEX page. Confirm that the schema is correct.',
'      Replace the placeholders with your OCI username and Auth Token.',
'    </div>',
'',
'    <pre style="background: #18212b; color: #eef3f7; border-radius: 6px; padding: 16px; overflow-x: auto; white-space: pre;"><code>-- Verify that this is the schema used by your APEX page',
'SELECT USER AS parsing_schema FROM dual;',
'',
'-- Create the DBMS_CLOUD credential for OCI Object Storage',
'BEGIN',
'  DBMS_CLOUD.CREATE_CREDENTIAL(',
'    credential_name =&gt; ''OCI_OBJECTSTORE_CRED'',',
'    username        =&gt; ''&lt;OCI username&gt;'',',
'    password        =&gt; ''&lt;OCI Auth Token&gt;''',
'  );',
'END;',
'/',
'',
'COMMIT;</code></pre>',
'',
'    <div style="font-size: 14px; color: #546e7a; margin-top: 8px;">',
unistr('      \D83D\DD12 Do not put the real Auth Token in this HTML region or in a shared, saved SQL Script.'),
'    </div>',
'  </div>',
'',
'  <div style="border: 1px solid #dce3e8; border-radius: 6px; padding: 16px 18px; margin-bottom: 20px;">',
'    <div style="font-size: 19px; font-weight: 700; margin-bottom: 6px;">',
unistr('      \D83D\DD04 Step 2: Run the SQL Script'),
'    </div>',
'    <div style="color: #455a64; margin-bottom: 10px;">',
'      Replace <code>40</code> with the required product ID in both filters. If you change the product ID,',
'      also update the CSV filename in the Object Storage URI.',
'    </div>',
'',
'    <pre style="background: #18212b; color: #eef3f7; border-radius: 6px; padding: 16px; overflow-x: auto; white-space: pre;"><code>-- Replace 40 with the required PRODUCT_ID.',
'-- Run the whole script together.',
'',
'BEGIN',
'    DELETE FROM CTS_ORDER_ITEMS_GTT;',
'',
'    INSERT INTO CTS_ORDER_ITEMS_GTT',
'           (ORDER_ID, LINE_ITEM_ID, PRODUCT_ID, UNIT_PRICE, QUANTITY)',
'    SELECT ORDER_ID, LINE_ITEM_ID, PRODUCT_ID, UNIT_PRICE, QUANTITY',
'    FROM CTS_ORDER_ITEMS',
'    WHERE PRODUCT_ID = 40;',
'',
'    UPDATE CTS_ORDER_ITEMS_GTT',
'    SET QUANTITY = QUANTITY + 1;',
'',
'    MERGE INTO CTS_ORDER_ITEMS t',
'    USING CTS_ORDER_ITEMS_GTT s',
'       ON (t.ORDER_ID = s.ORDER_ID',
'       AND t.LINE_ITEM_ID = s.LINE_ITEM_ID)',
'    WHEN MATCHED THEN',
'        UPDATE SET t.QUANTITY = s.QUANTITY;',
'',
'    COMMIT;',
'',
'    DBMS_CLOUD.EXPORT_DATA(',
'        credential_name =&gt; ''OCI_OBJECTSTORE_CRED'',',
'        file_uri_list   =&gt; ''https://objectstorage.<region>.oraclecloud.com/n/<namespace>/b/<bucketname>/o/<object-name>'',',
'        format          =&gt; JSON_OBJECT(''type'' VALUE ''csv'', ''header'' VALUE true),',
'        query           =&gt; ''SELECT ORDER_ID, LINE_ITEM_ID, PRODUCT_ID, UNIT_PRICE, QUANTITY',
'                            FROM CTS_ORDER_ITEMS',
'                            WHERE PRODUCT_ID = 40',
'                            ORDER BY ORDER_ID, LINE_ITEM_ID''',
'    );',
'END;',
'/</code></pre>',
'',
'    <div style="background: #fff8e1; border-left: 5px solid #f9a825; border-radius: 6px; padding: 12px 15px; margin-top: 14px;">',
unistr('      <div style="font-weight: 700; margin-bottom: 4px;">\26A0\FE0F The script changes data</div>'),
'      <div>',
'        It adds 1 to the matching quantities and commits those changes before exporting the CSV.',
'        If the export fails after the commit, the data update may still have succeeded.',
'        Check the table before rerunning, or the quantities may be increased again.',
'      </div>',
'    </div>',
'  </div>',
'',
'  <div style="border: 1px solid #dce3e8; border-radius: 6px; padding: 16px 18px; margin-bottom: 20px;">',
'    <div style="font-size: 19px; font-weight: 700; margin-bottom: 6px;">',
unistr('      \2B07\FE0F Step 3: Add the APEX download process'),
'    </div>',
'    <div style="color: #455a64; margin-bottom: 10px;">',
'      Create a server-side PL/SQL process that runs when the user submits a Download button.',
'      It retrieves the CSV created in Step 2 and sends it to the browser.',
'    </div>',
'',
'    <pre style="background: #18212b; color: #eef3f7; border-radius: 6px; padding: 16px; overflow-x: auto; white-space: pre;"><code>DECLARE',
'    l_file BLOB;',
'BEGIN',
'    l_file := DBMS_CLOUD.GET_OBJECT(',
'        credential_name =&gt; ''OCI_OBJECTSTORE_CRED'',',
'        object_uri      =&gt; ''https://objectstorage.us-chicago-1.oraclecloud.com/n/axlgmb1cvtyd/b/CTS/o/cts_order_items_product_40.csv''',
'    );',
'',
'    APEX_HTTP.DOWNLOAD(',
'        p_blob         =&gt; l_file,',
'        p_content_type =&gt; ''text/csv'',',
'        p_filename     =&gt; ''cts_order_items_product_40.csv'',',
'        p_is_inline    =&gt; FALSE',
'    );',
'END;</code></pre>',
'  </div>',
'',
'  <div style="background: #f5f8fa; border-radius: 6px; padding: 14px 18px;">',
unistr('    <div style="font-weight: 700; margin-bottom: 4px;">\D83D\DCDD How the pieces work together</div>'),
'    <ul style="margin: 6px 0 0 20px; padding: 0;">',
'      <li><code>CTS_ORDER_ITEMS_GTT</code> temporarily holds the selected product rows while the quantity is changed.</li>',
'      <li><code>MERGE</code> applies the changed quantities to <code>CTS_ORDER_ITEMS</code>.</li>',
'      <li><code>DBMS_CLOUD.EXPORT_DATA</code> writes the matching main-table rows as a CSV object in the bucket.</li>',
'      <li><code>DBMS_CLOUD.GET_OBJECT</code> reads that object, and <code>APEX_HTTP.DOWNLOAD</code> sends it to the browser.</li>',
'    </ul>',
'  </div>',
'',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261022160304Z')
,p_updated_on=>wwv_flow_imp.dz('20261022161238Z')
,p_created_by=>'SANTHOSH'
,p_updated_by=>'SANTHOSH'
);
end;
