,p_plug_name=>'Explanation'
,p_static_id=>'explanation'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3372714138756020509
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="t-Alert t-Alert--info" role="note" style="margin: 1rem 0;">',
'  <div class="t-Alert-content" style="padding: 1.25rem 1.5rem;">',
'',
'    <div style="display: flex; align-items: flex-start; gap: 0.85rem; margin-bottom: 1rem;">',
'      <span class="fa fa-database"',
'            aria-hidden="true"',
'            style="font-size: 1.5rem; margin-top: 0.15rem;"></span>',
'      <div>',
'        <h2 class="t-Alert-title" style="margin: 0 0 0.35rem;">',
'          Update order items for the selected product',
'        </h2>',
'        <p style="margin: 0; line-height: 1.6;">',
'          This process stages matching order items in a Global Temporary Table (GTT),',
'          increases their quantity, then applies the changes to',
'          <strong>CTS_ORDER_ITEMS</strong>.',
'        </p>',
'      </div>',
'    </div>',
'',
'    <ol style="margin: 0 0 1rem 1.25rem; padding: 0; line-height: 1.7;">',
'      <li style="margin-bottom: 0.45rem;">',
'        <span class="fa fa-trash" aria-hidden="true"></span>',
'        Clear the GTT before starting.',
'      </li>',
'      <li style="margin-bottom: 0.45rem;">',
'        <span class="fa fa-filter" aria-hidden="true"></span>',
'        Copy only rows whose <strong>PRODUCT_ID</strong> matches the selected product',
'        in <code>Product</code> drop-down.',
'      </li>',
'      <li style="margin-bottom: 0.45rem;">',
'        <span class="fa fa-plus-circle" aria-hidden="true"></span>',
'        Increase the staged <strong>QUANTITY</strong> by 1.',
'      </li>',
'      <li>',
'        <span class="fa fa-refresh" aria-hidden="true"></span>',
'        Merge the updated quantities back, matching each row by',
'        <strong>ORDER_ID</strong> and <strong>LINE_ITEM_ID</strong>.',
'      </li>',
'    </ol>',
'',
'    <p style="margin: 0 0 0.75rem; line-height: 1.6;">',
'      <span class="fa fa-check-circle" aria-hidden="true"></span>',
'      <strong>Result:</strong> Only order lines for the selected product are updated.',
'    </p>',
'',
'    <p style="margin: 0; padding-top: 0.75rem; border-top: 1px solid rgba(127,127,127,0.3); line-height: 1.6;">',
'      <span class="fa fa-clock-o" aria-hidden="true"></span>',
'      <strong>Session note:</strong> Run the steps in the same database session.',
'      The final <code>COMMIT</code> saves the main-table changes and, with',
'      <code>ON COMMIT DELETE ROWS</code>, clears the GTT data.',
'    </p>',
'',
'  </div>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
