,p_lov_display_null=>'YES'
,p_lov_null_text=>'--product--'
,p_cHeight=>1
,p_field_template=>1610598304472262251
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_created_on=>wwv_flow_imp.dz('20261022144843Z')
,p_updated_on=>wwv_flow_imp.dz('20261022151258Z')
,p_created_by=>'SANTHOSH'
,p_updated_by=>'SANTHOSH'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(92779257672599512)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'try-gtt'
,p_static_id=>'new'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DELETE FROM CTS_ORDER_ITEMS_GTT;',
'',
'INSERT INTO CTS_ORDER_ITEMS_GTT',
'       (ORDER_ID, LINE_ITEM_ID, PRODUCT_ID, UNIT_PRICE, QUANTITY)',
'SELECT ORDER_ID, LINE_ITEM_ID, PRODUCT_ID, UNIT_PRICE, QUANTITY',
'FROM CTS_ORDER_ITEMS',
'WHERE PRODUCT_ID = :P2_PRODUCT',
'-- Add a WHERE clause here to limit rows if appropriate',
';',
'',
'UPDATE CTS_ORDER_ITEMS_GTT',
'SET QUANTITY = QUANTITY + 1;',
'',
'MERGE INTO CTS_ORDER_ITEMS t',
'USING CTS_ORDER_ITEMS_GTT s',
'   ON (t.ORDER_ID = s.ORDER_ID',
'   AND t.LINE_ITEM_ID = s.LINE_ITEM_ID)',
'WHEN MATCHED THEN',
'    UPDATE SET t.QUANTITY = s.QUANTITY;',
'',
'COMMIT;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>92779257672599512
,p_created_on=>wwv_flow_imp.dz('20261022144346Z')
,p_updated_on=>wwv_flow_imp.dz('20261022150910Z')
,p_created_by=>'SANTHOSH'
,p_updated_by=>'SANTHOSH'
);
end;
